contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        bool reverted;
        uint before = address(c).balance;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBal = address(c).balance;
        assert(reverted ? afterBal == before : afterBal == 0);
    }

    receive() external payable {}
}

