    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 cBalanceBefore = address(c).balance;
        uint256 thisBalanceBefore = address(this).balance;

        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("sudicideAnyone()"));

        assert(success && address(this).balance == thisBalanceBefore + cBalanceBefore + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Fund c so that the successful call must move a nonzero balance.
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);

        // InvMutTest is the owner of c (it deployed c); call the owner-only entrypoint.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the owner's call succeeds, c is destroyed (no code), and the
        // funded balance was transferred out of c to the owner (this test contract).
        assert(!reverted && address(c).code.length == 0 && address(c).balance == 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // InvMutTest deployed c, so it is the owner.
        // The deciding call: owner-only selfdestruct entrypoint.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the owner's call must succeed (not revert), the contract
        // must be destroyed (no code remains), and its Ether balance must be zero
        // regardless of how much was funded before.
        assert(!reverted && address(c).code.length == 0 && address(c).balance == 0);
    }

    receive() external payable {}
}

