contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(address(this).balance >= 0);
        require(caller != address(0));
        require(caller != address(this));

        uint256 balBefore = address(c).balance;
        bool reverted;

        // Drive the public entry as the test contract (non-owner in practice).
        // Since run() is called by the harness, msg.sender for c.sudicideAnyone() is always
        // address(this), which is the deployer only if the harness did not deploy c. The rule
        // below remains non-trivial either way: destruction and balance movement are linked.
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // General rule: if selfdestruct succeeds, c's balance must have moved away from c
        // (to the caller), and if it does not succeed, no balance change is allowed.
        if (reverted) {
            assert(balAfter == balBefore);
        } else {
            assert(balAfter == 0);
        }
    }

    receive() external payable {}
}

