contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // Precondition: this test contract is the owner (it deployed c).
        // Record sender's and c's balances before the call.
        uint beforeSenderBal = address(this).balance;
        uint beforeCBal = address(c).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterSenderBal = address(this).balance;
        uint afterCBal = address(c).balance;

        // General rule: sudicideAnyone either reverts and leaves both balances unchanged,
        // or completes and leaves c with zero balance (and the test contract's balance
        // may increase by c's previous balance). In all cases the two calls are mutually exclusive.
        assert(
            (reverted && afterSenderBal == beforeSenderBal && afterCBal == beforeCBal) ||
            (!reverted && afterCBal == 0 && (afterSenderBal == beforeSenderBal + beforeCBal))
        );
    }

    receive() external payable {}
}

